function can(user, permission) {
  return (ROLE_PERMISSIONS[user?.role] || []).includes(permission);
}

// Calls our backend, which fans out to the configured provider
// (Claude / OpenAI / Gemini). `provider` is optional; server default is used
// when omitted. Reads window.__AI_PROVIDER if the UI switcher set one.
async function callClaude(userPrompt, system) {
  const provider = typeof window !== "undefined" ? (window as any).__AI_PROVIDER : undefined;
  const res = await fetch(AI_PROXY, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      provider,
      system: system || "You are a KB author for a B2B SaaS CS team. Return only valid JSON, no markdown.",
      prompt: userPrompt,
      maxTokens: 1000,
    }),
  });
  if (!res.ok) throw new Error(`AI request failed: ${res.status}`);
  const data = await res.json();
  return data.text || "";
}

